        }
      ],
      "explanation": "The doctor did not treat the residual monitored/persecutory content as ordinary anxiety or rebellion; later advice appropriately linked it to relapse/residual psychosis risk and psychiatric emergency follow-up when home care was unsafe.",
      "issue_kind": "none",
      "rc_id": "RC2_residual_psychosis_and_recent_discharge",
      "status": "met"
    },
    {
      "citations": [
        {
